STORIES = [
    (
        "Poland activates air defence as Russian drone enters its airspace",
        "A Russian drone crossed into Poland near Dorohusk during overnight "
        "strikes on Ukraine; NATO weighs new European troop moves.",
    ),
    (
        "Trump says he brought Jensen Huang back to Nvidia",
        "The US president claims he persuaded Nvidia's board to restore its "
        "chief, as espionage probes and a scramble for AI chips shake the firm.",
    ),
    (
        "Ukraine reports fresh Russian strikes on Kyiv region",
        "New drone and missile attacks hit the capital region as rescue teams "
        "assess the damage and aid affected residents.",
    ),
    (
        "COP31 climate talks stall in Turkiye",
        "Nations remain split over fossil fuels, finance for developing "
        "countries and environmental commitments.",
    ),
    (
        "Iran warns of countermeasures as US naval pressure mounts",
        "Tehran warns against a US naval blockade while Washington warns of a "
        "'very traumatic' outcome if the nuclear deal fails.",
    ),
    (
        "Indonesia factory fire kills several, workers missing",
        "A major blaze at an industrial facility leaves casualties and missing "
        "workers; rescue operations continue.",
    ),
]


def font(name, size):
    path = "/usr/share/fonts/truetype/dejavu/" + name
    try:
        return ImageFont.truetype(path, size)
    except OSError:
        return ImageFont.load_default()


def wrap(draw, text, fnt, max_w):
    words = text.split()
    lines, cur = [], ""
    for w in words:
        trial = (cur + " " + w).strip()
        if draw.textlength(trial, font=fnt) <= max_w:
            cur = trial
        else:
            if cur:
                lines.append(cur)
            cur = w
    if cur:
        lines.append(cur)
    return lines


def main():
    img = Image.new("RGB", (W, H), WHITE)
    d = ImageDraw.Draw(img)

    # ---- header ----
    d.rectangle([0, 0, W, 190], fill=NAVY)
    d.rectangle([0, 186, W, 190], fill=AMBER)
    f_title = font("DejaVuSans-Bold.ttf", 64)
    f_date = font("DejaVuSans.ttf", 30)
    d.text((60, 42), "WORLD NEWS", font=f_title, fill=WHITE)
    d.text((60, 122), "TUESDAY  \u2022  24 NOVEMBER 2026", font=f_date, fill=AMBER)

    # ---- hero banner ----
    hero = Image.open(io.BytesIO(base64.b64decode(HERO_B64))).convert("RGB")
    img.paste(hero, (0, 190))
    d.rectangle([0, 550, W, 590], fill=(0, 0, 0))
    f_cap = font("DejaVuSans.ttf", 24)
    d.text((60, 556), "THE DAY IN SIX STORIES", font=f_cap, fill=WHITE)

    # ---- stories ----
    f_num = font("DejaVuSans-Bold.ttf", 34)
    f_head = font("DejaVuSans-Bold.ttf", 33)
    f_sum = font("DejaVuSans.ttf", 26)
    y = 630
    text_x = 150
    text_w = W - text_x - 60
    for i, (head, summ) in enumerate(STORIES, 1):
        cx, cy = 105, y + 28
        d.ellipse([cx - 32, cy - 32, cx + 32, cy + 32], fill=AMBER)
        d.text((cx, cy), str(i), font=f_num, fill=NAVY, anchor="mm")
        lines = wrap(d, head, f_head, text_w)
        ly = y
        for ln in lines[:2]:
            d.text((text_x, ly), ln, font=f_head, fill=INK)
            ly += 40
        slines = wrap(d, summ, f_sum, text_w)
        sy = ly + 4
        for ln in slines[:2]:
            d.text((text_x, sy), ln, font=f_sum, fill=GREY)
            sy += 34
        y = sy + 26
        if i < len(STORIES):
            d.line([60, y - 12, W - 60, y - 12], fill=LINE, width=2)

    # ---- footer ----
    d.rectangle([0, H - 64, W, H], fill=LIGHT)
    f_foot = font("DejaVuSans.ttf", 22)
    d.text(
        (60, H - 46),
        "Top stories of 24 November 2026  \u2022  Sources: major news wires",
        font=f_foot,
        fill=GREY,
    )

    img.save(OUT, "PNG")
    print("wrote", OUT, img.size)


if __name__ == "__main__":
    main()
